'use client';

let detectorInstance: any = null;
let detectorPromise: Promise<any> | null = null;

export async function createPoseDetector() {
  // Return cached detector if already created
  if (detectorInstance) return detectorInstance;

  // Avoid race condition: if creation is in progress, wait for it
  if (detectorPromise) return detectorPromise;

  detectorPromise = (async () => {
    // Server-side guard
    if (typeof window === 'undefined') {
      throw new Error('TensorFlow.js cannot run on server');
    }

    try {
      const tf = await import('@tensorflow/tfjs-core');
      await import('@tensorflow/tfjs-backend-webgl');

      // Wait for backend to register
      await tf.ready();

      const poseDetection = await import('@tensorflow-models/pose-detection');

      detectorInstance = await poseDetection.createDetector(
        poseDetection.SupportedModels.BlazePose,
        { 
          runtime: 'tfjs', 
          modelType: 'lite' // Use 'lite' for speed, not 'full'
        }
      );

      return detectorInstance;
    } catch (error) {
      console.error('Failed to initialize pose detector:', error);
      detectorPromise = null; // Reset on error
      throw error;
    }
  })();

  return detectorPromise;
}

export async function estimatePoses(videoElement: HTMLVideoElement) {
  // Guard: server-side
  if (typeof window === 'undefined') return [];

  // Guard: video element validity
  if (videoElement.videoWidth === 0 || videoElement.videoHeight === 0) return [];
  if (videoElement.readyState < 2) return [];

  try {
    const detector = await createPoseDetector();
    return await detector.estimatePoses(videoElement, { maxPoses: 1 });
  } catch (error) {
    console.error('Pose estimation failed:', error);
    return [];
  }
}

