`cartStore.ts` and `AdminProductManager.tsx` both import from `@/lib/shopify`, which didn't exist, causing a hard Vite import-analysis failure at startup.

## Changes

- **`src/lib/shopify.ts`** — new compatibility module:
  - `ShopifyProduct` — type alias for `Product` from `@/lib/catalog`
  - `fetchProducts` — re-exported from `@/lib/catalog`
  - `createStorefrontCheckout(items)` — delegates to the `create-checkout` edge function via `safeInvoke`, returning the checkout URL; dual-field fallback (`sessionUrl || url`) matches the existing pattern in `Checkout.tsx`

```ts
export type { Product as ShopifyProduct } from '@/lib/catalog';
export { fetchProducts } from '@/lib/catalog';

export async function createStorefrontCheckout(items: LineItem[]): Promise<string> {
  const { data, error } = await safeInvoke<{ url?: string; sessionUrl?: string }>('create-checkout', {
    body: { items },
  });
  const url = data?.sessionUrl || data?.url;
  if (!url) throw new Error('No checkout URL returned from create-checkout');
  return url;
}
```

